const dbp=new Promise((res,rej)=>{let r=indexedDB.open('one-station',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts',{keyPath:'id'});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});
